inst = inst.copy() if copy else inst
ch_dict = {**{type_: True for type_ in ch_type}, "meg": False, "ref_meg": False}
ch_sel = [inst.ch_names[i] for i in pick_types(inst.info, **ch_dict)]

# An average reference over several channel types is computed separately
# for each channel type, mirroring the default (joint=False) projector
# route above, so that both application routes implement the same
# operation.
separate_average = (
    ref_channels == "average" and len(ch_type) > 1 and len(ch_sel) > 0
)

if ref_channels == "REST":
    _validate_type(forward, Forward, 'forward when ref_channels="REST"')
else:
    forward = None  # signal to _apply_reference not to do REST

if ref_channels in ("average", "REST"):
    logger.info(f"Applying {ref_channels} reference.")
    ref_channels = ch_sel

if ref_channels == []:
    logger.info("EEG data marked as already having the desired reference.")
else:
    logger.info(
        "Applying a custom "
        f"{tuple(DEFAULTS['titles'][type_] for type_ in ch_type)} "
        "reference."
    )

if separate_average:
    ref_data = {}
    for this_ch_type in ch_type:
        this_sel = [
            inst.ch_names[i]
            for i in pick_types(
                inst.info,
                **{this_ch_type: True, "meg": False, "ref_meg": False},
            )
        ]
        if len(this_sel) == 0:
            continue
        inst, ref_data[this_ch_type] = _apply_reference(
            inst, this_sel, this_sel, ch_type=[this_ch_type]
        )
    return inst, ref_data

return _apply_reference(inst, ref_channels, ch_sel, forward, ch_type=ch_type)

